import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const repoRoot = resolve(__dirname, '../..')

export const GUIDES = [
  {
    source: resolve(repoRoot, 'docs/platform/SUPERADMIN_GUIDE.md'),
    out: resolve(__dirname, '../content/guides/superadmin-guide.ts'),
  },
  {
    source: resolve(repoRoot, 'docs/platform/SUBADMIN_GUIDE.md'),
    out: resolve(__dirname, '../content/guides/subadmin-guide.ts'),
  },
]

const BANNER =
  '// AUTO-GENERATED by scripts/sync-guides.mjs — do not edit.\n' +
  '// Source of truth: docs/platform/*.md. Run `npm run sync:guides` to regenerate.\n'

export function buildModuleSource(markdown) {
  return `${BANNER}export default ${JSON.stringify(markdown)}\n`
}

export function checkInSync(markdown, moduleText) {
  return moduleText === buildModuleSource(markdown)
}

function main() {
  const check = process.argv.includes('--check')
  const drifted = []
  for (const { source, out } of GUIDES) {
    const markdown = readFileSync(source, 'utf8')
    const expected = buildModuleSource(markdown)
    if (check) {
      let current = ''
      try {
        current = readFileSync(out, 'utf8')
      } catch {
        current = ''
      }
      if (current !== expected) drifted.push(out)
    } else {
      writeFileSync(out, expected, 'utf8')
      process.stdout.write(`wrote ${out}\n`)
    }
  }
  if (check && drifted.length > 0) {
    process.stderr.write(
      `Guide modules out of sync:\n${drifted.join('\n')}\nRun: npm run sync:guides\n`,
    )
    process.exit(1)
  }
}

// Cross-platform main-module guard (works on Windows where file:// paths differ from argv[1])
const __filename = fileURLToPath(import.meta.url)
const { resolve: _resolve } = await import('node:path')
if (process.argv[1] && _resolve(process.argv[1]) === __filename) {
  main()
}
